#include <stdio.h>
#include <string.h>

int h, w;
long long dp[2][1<<10];

int main() {
    scanf("%d %d", &h, &w);
    if (h > w) { int t = h; h = w; w = t; }

    int cur = 0;
    int full = (1 << h) - 1;
    dp[cur][full] = 1;

    for (int col = 0; col < w; col++) {
        for (int row = 0; row < h; row++) {
            memset(dp[cur ^ 1], 0, sizeof(dp[cur ^ 1]));
            for (int mask = 0; mask <= full; mask++) {
                if (!dp[cur][mask]) continue;
                // Place horizontal (1x2) if possible
                if (!(mask & (1 << row))) {
                    // Already occupied
                    continue;
                }
                // Place vertical (2x1) mat
                if (row + 1 < h && (mask & (1 << (row+1)))) {
                    int newmask = mask & ~(1 << row) & ~(1 << (row+1));
                    dp[cur ^ 1][newmask] += dp[cur][mask];
                }
                // Place horizontal mat: occupies this cell and extends to next column
                // This means we leave current cell occupied in next column's mask
                int newmask = mask & ~(1 << row);
                dp[cur ^ 1][newmask] += dp[cur][mask];
            }
            cur ^= 1;
        }
        // After finishing the column, check no full vertical seam
        // Actually we must forbid mask == full at any point except maybe last column
        // Forbidden: all bits set means a full vertical seam
        // After finishing column, if mask == full, that's a seam - we must discard
        for (int mask = 0; mask <= full; mask++) {
            if (mask == full && col != w-1) {
                dp[cur][mask] = 0;
            }
        }
    }

    printf("%lld\n", dp[cur][full]);
    return 0;
}

