int H, W;
int grid[12][12]; // 0 = empty, 1 = filled
// hseam[i][j] = 1 if there's a horizontal seam between row i-1 and row i at column j (0-indexed)
// vseam[i][j] = 1 if there's a vertical seam between col j-1 and col j at row i
int hseam[12][12], vseam[12][12];
long long count;

int check_cross(int r, int c) {
    // Check all interior points adjacent to cell (r,c)
    // Interior points are (r,c), (r,c+1), (r+1,c), (r+1,c+1) - corners of the cell
    for (int pr = r; pr <= r+1; pr++) {
        for (int pc = c; pc <= c+1; pc++) {
            if (pr > 0 && pr < H && pc > 0 && pc < W) {
                if (hseam[pr][pc] && vseam[pr][pc]) return 0;
            }
        }
    }
    return 1;
}

void solve(int pos) {
    while (pos < H*W && grid[pos/W][pos%W]) pos++;
    if (pos == H*W) { count++; return; }
    int r = pos/W, c = pos%W;
    // Try horizontal
    if (c+1 < W && !grid[r][c+1]) {
        grid[r][c] = grid[r][c+1] = 1;
        vseam[r][c+1] = 1;
        if (r > 0) hseam[r][c] = 1, hseam[r][c+1] = 1; // no, seams are edges of this domino
        // horizontal domino: top/bottom seams at r and r+1 for cols c and c+1; right seam at c+1
        // Actually let me just check after placing
        if (check_cross(r,c)) solve(pos+1);
        grid[r][c] = grid[r][c+1] = 0;
        vseam[r][c+1] = 0;
    }
    // Try vertical
    if (r+1 < H && !grid[r+1][c]) {
        grid[r][c] = grid[r+1][c] = 1;
        hseam[r+1][c] = 1;
        if (check_cross(r,c)) solve(pos+1);
        grid[r][c] = grid[r+1][c] = 0;
        hseam[r+1][c] = 0;
    }
}

int main() {
    while (scanf("%d %d", &H, &W) == 2 && (H||W)) {
        if ((H*W)%2) { printf("0\n"); continue; }
        memset(grid,0,sizeof(grid)); memset(hseam,0,sizeof(hseam)); memset(vseam,0,sizeof(vseam));
        count = 0; solve(0); printf("%lld\n", count);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
  Count tatami tilings of an H x W rectangle by 1x2 dominoes
  with the "no four corners meet" rule ("tatami" condition).

  We process the board cell by cell in row-major order.
  A state keeps:
    - occ mask for current row and next row:
        bit i      : cell (r, i) already occupied
        bit W + i  : cell (r+1, i) already occupied
    - vmask for current row boundaries between row r-1 and r:
        bit i is 1 if there is a vertical domino crossing that boundary at column i

  While placing a domino at cell (r,c), we can check whether a 2x2 vertex
  gets completed and whether all four incident half-edges exist:
    at interior vertex between rows r/r+1 and cols c/c+1.

  Edge existence around such a vertex:
    top    : horizontal at row r, between cols c and c+1
    bottom : horizontal at row r+1, between cols c and c+1
    left   : vertical between rows r and r+1 at col c
    right  : vertical between rows r and r+1 at col c+1

  We detect a forbidden cross exactly when the last missing edge of such a set
  is added.

  Constraints are not given, but this standard DP works well for widths up to ~8-10.
*/

typedef unsigned long long ULL;

typedef struct {
    int occ;
    int vmask;
    ULL cnt;
    int used;
} Entry;

typedef struct {
    Entry *a;
    int cap;
} Hash;

static int H, W;
static int FULLW;
static int OCCBITS;
static int MASKOCC;
static int MASKV;

static unsigned hash_key(int occ, int vmask) {
    unsigned x = (unsigned)occ * 1000003u ^ (unsigned)vmask * 911382323u;
    x ^= x >> 16;
    return x;
}

static void hash_init(Hash *h, int cap) {
    h->cap = cap;
    h->a = (Entry*)calloc(cap, sizeof(Entry));
}

static void hash_clear(Hash *h) {
    memset(h->a, 0, sizeof(Entry) * h->cap);
}

static void hash_add(Hash *h, int occ, int vmask, ULL add) {
    unsigned idx = hash_key(occ, vmask) % h->cap;
    while (h->a[idx].used) {
        if (h->a[idx].occ == occ && h->a[idx].vmask == vmask) {
            h->a[idx].cnt += add;
            return;
        }
        idx++;
        if (idx == (unsigned)h->cap) idx = 0;
    }
    h->a[idx].used = 1;
    h->a[idx].occ = occ;
    h->a[idx].vmask = vmask;
    h->a[idx].cnt = add;
}

static int has_horizontal(int occ, int rowOffset, int c) {
    /* rowOffset = 0 for current row, 1 for next row */
    int base = rowOffset * W;
    return ((occ >> (base + c)) & 1) && ((occ >> (base + c + 1)) & 1);
}

static int cross_if_place_horizontal(int occ_before, int vmask, int rowOffset, int c) {
    /* placing horizontal at rowOffset, columns c,c+1 */
    /* check vertices adjacent to this horizontal edge */
    if (c < 0 || c + 1 >= W) return 0;

    int leftcol = c;
    int rightcol = c + 1;

    if (rowOffset == 0) {
        /* top edge of vertex at rows 0/1, cols c/c+1 */
        if (H >= 2) {
            int bottom = has_horizontal(occ_before, 1, c);
            int left = (vmask >> leftcol) & 1;
            int right = (vmask >> rightcol) & 1;
            if (bottom && left && right) return 1;
        }
    } else {
        /* bottom edge of vertex at rows 0/1, cols c/c+1 */
        int top = has_horizontal(occ_before, 0, c);
        int left = (vmask >> leftcol) & 1;
        int right = (vmask >> rightcol) & 1;
        if (top && left && right) return 1;
    }
    return 0;
}

static int cross_if_place_vertical(int occ_before, int vmask, int c) {
    /* placing vertical between current row and next row at column c */
    /* check vertex to the left: cols c-1/c */
    if (c - 1 >= 0) {
        int top = has_horizontal(occ_before, 0, c - 1);
        int bottom = has_horizontal(occ_before, 1, c - 1);
        int left = (vmask >> (c - 1)) & 1;
        if (top && bottom && left) return 1;
    }
    /* check vertex to the right: cols c/c+1 */
    if (c + 1 < W) {
        int top = has_horizontal(occ_before, 0, c);
        int bottom = has_horizontal(occ_before, 1, c);
        int right = (vmask >> (c + 1)) & 1;
        if (top && bottom && right) return 1;
    }
    return 0;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;

    /* Symmetry: keep width smaller for state compression */
    if (W > H) {
        int t = W; W = H; H = t;
    }

    if ((H * W) & 1) {
        printf("0\n");
        return 0;
    }

    FULLW = 1 << W;
    OCCBITS = 2 * W;
    MASKOCC = (1 << OCCBITS) - 1;
    MASKV = (1 << W) - 1;

    Hash cur, nxt;
    hash_init(&cur, 1 << 20);
    hash_init(&nxt, 1 << 20);

    hash_add(&cur, 0, 0, 1);

    for (int r = 0; r < H; r++) {
        for (int c = 0; c < W; c++) {
            hash_clear(&nxt);

            for (int i = 0; i < cur.cap; i++) if (cur.a[i].used) {
                int occ = cur.a[i].occ;
                int vmask = cur.a[i].vmask;
                ULL ways = cur.a[i].cnt;

                if ((occ >> c) & 1) {
                    hash_add(&nxt, occ, vmask, ways);
                    continue;
                }

                /* Try horizontal in current row */
                if (c + 1 < W && (((occ >> (c + 1)) & 1) == 0)) {
                    if (!cross_if_place_horizontal(occ, vmask, 0, c)) {
                        int occ2 = occ | (1 << c) | (1 << (c + 1));
                        hash_add(&nxt, occ2, vmask, ways);
                    }
                }

                /* Try vertical downward */
                if (r + 1 < H && (((occ >> (W + c)) & 1) == 0)) {
                    if (!cross_if_place_vertical(occ, vmask, c)) {
                        int occ2 = occ | (1 << c) | (1 << (W + c));
                        int v2 = vmask | (1 << c);
                        hash_add(&nxt, occ2, v2, ways);
                    }
                }
            }

            Hash tmp = cur; cur = nxt; nxt = tmp;
        }

        /* move to next row:
           next row occupancy becomes current row occupancy,
           new next row empty,
           vertical mask for next boundary:
             keep only verticals crossing from old next row to new next row+1 -> none yet
           but current boundary for next row is exactly the verticals we placed between old row and old row+1,
           which are stored in vmask and must become "previous boundary" for row shift.
           Since our state interprets vmask as verticals between current row and next row,
           after shifting rows, those old verticals become between previous/current, so they are no longer needed
           except for cross checks involving current boundary. For the next row, the current boundary starts with 0.
           However the occupied current row already encodes cells covered from above.
        */
        hash_clear(&nxt);
        for (int i = 0; i < cur.cap; i++) if (cur.a[i].used) {
            int occ = cur.a[i].occ;
            ULL ways = cur.a[i].cnt;

            /* current row must be fully occupied */
            if ((occ & MASKV) != MASKV) continue;

            int newOcc = (occ >> W) & MASKV; /* old next row becomes new current row */
            hash_add(&nxt, newOcc, 0, ways);
        }
        Hash tmp = cur; cur = nxt; nxt = tmp;
    }

    ULL ans = 0;
    for (int i = 0; i < cur.cap; i++) if (cur.a[i].used) {
        if (cur.a[i].occ == 0) ans += cur.a[i].cnt;
    }

    printf("%llu\n", ans);

    free(cur.a);
    free(nxt.a);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int H, W;
// dp[mask][row] stores number of ways for current row with given mask
// We'll use two rows to save memory
long long dp[2][1<<12];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> H >> W;

    // Ensure W <= H for efficiency (we can transpose)
    if (W > H) swap(H, W);

    int fullMask = (1 << W) - 1;

    // Initialize dp for row 0 (before first row)
    dp[0][fullMask] = 1;

    for (int row = 0; row < H; ++row) {
        int cur = row & 1;
        int nxt = (row + 1) & 1;
        // Reset next row
        fill(dp[nxt], dp[nxt] + (1<<W), 0);

        // Iterate over all masks for current row
        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[cur][mask] == 0) continue;
            // Use DFS to fill current row based on mask
            // mask indicates which cells are already occupied from above (vertical placement)
            function<void(int, int, long long)> dfs = [&](int col, int nextMask, long long ways) {
                if (col >= W) {
                    dp[nxt][nextMask] += ways;
                    return;
                }
                // If cell is already occupied from above
                if (mask & (1 << col)) {
                    // Cannot place horizontal here because it would cross with vertical
                    // Just move to next column, no new occupation for next row
                    dfs(col + 1, nextMask & ~(1 << col), ways);
                } else {
                    // Option 1: Place vertical tatami (1x2)
                    // This occupies current cell in this row and below
                    // So next row gets this cell occupied
                    dfs(col + 1, nextMask | (1 << col), ways);

                    // Option 2: Place horizontal tatami (2x1)
                    if (col + 1 < W && !(mask & (1 << (col+1)))) {
                        // Both cells must be free in current row
                        // No effect on next row
                        dfs(col + 2, nextMask & ~((1 << col) | (1 << (col+1))), ways);
                    }
                }
            };

            dfs(0, 0, dp[cur][mask]);
        }
    }

    // After last row, we need fullMask (all cells occupied from above)
    cout << dp[H & 1][fullMask] << "\n";

    return 0;
}

