int H, W;
int board[10][10]; // domino id
int cnt;
int domino_cnt;

bool checkCross(int r, int c) {
    // Check cross at interior point (r,c): between rows r-1,r and cols c-1,c
    if (r < 1 || r >= H || c < 1 || c >= W) return false;
    return (board[r-1][c-1] != board[r-1][c] && 
            board[r-1][c-1] != board[r][c-1] && 
            board[r-1][c-1] != board[r][c] &&
            board[r-1][c] != board[r][c-1] && 
            board[r-1][c] != board[r][c] &&
            board[r][c-1] != board[r][c]);
}

void solve(int pos) {
    if (pos == H * W) { cnt++; return; }
    int r = pos / W, c = pos % W;
    if (board[r][c] != -1) { solve(pos + 1); return; }

    // Try horizontal
    if (c + 1 < W && board[r][c+1] == -1) {
        board[r][c] = board[r][c+1] = domino_cnt++;
        bool ok = true;
        // Check crosses at points (r,c), (r,c+1), (r+1,c), (r+1,c+1)
        for (int dr = 0; dr <= 1 && ok; dr++)
            for (int dc = 0; dc <= 2 && ok; dc++)
                if (checkCross(r+dr, c+dc)) ok = false;
        if (ok) solve(pos + 1);
        board[r][c] = board[r][c+1] = -1; domino_cnt--;
    }
    // Try vertical
    if (r + 1 < H && board[r+1][c] == -1) {
        board[r][c] = board[r+1][c] = domino_cnt++;
        bool ok = true;
        for (int dr = 0; dr <= 2 && ok; dr++)
            for (int dc = 0; dc <= 1 && ok; dc++)
                if (checkCross(r+dr, c+dc)) ok = false;
        if (ok) solve(pos + 1);
        board[r][c] = board[r+1][c] = -1; domino_cnt--;
    }
}

int main() {
    while (cin >> H >> W && (H || W)) {
        memset(board, -1, sizeof(board));
        cnt = 0; domino_cnt = 0;
        if ((H * W) % 2 == 0) solve(0);
        cout << cnt << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

/*
  Tatami tilings of an H x W rectangle by 1x2 dominoes,
  with the restriction that no four tatami corners meet at one point
  ("no cross" condition).

  We count all tilings.

  Approach:
  Sweep the board row by row, cell by cell.
  A state keeps:
    - occ: bitmask of cells in current row already occupied by vertical dominoes
           coming from the previous row, or by placements already made in this row.
    - vert: bitmask of cells in current row that are the TOP halves of vertical dominoes
            placed from this row to the next row.
    - leftH: for each column boundary j (between j-1 and j), whether that boundary
             in the current row is crossed by a horizontal domino.
             We encode boundaries 1..W-1 as bits 0..W-2.

  When placing a domino, we locally check every newly created interior grid point
  to ensure not all four incident edges are present.

  State transition from row r to r+1:
    next occ starts as previous vert, next vert = 0, next leftH = 0.

  Complexity is fine for typical tatami constraints.
*/

struct State {
    int occ, vert, hmask;
    bool operator==(const State& other) const {
        return occ == other.occ && vert == other.vert && hmask == other.hmask;
    }
};

struct Hasher {
    size_t operator()(const State& s) const {
        return ((size_t)s.occ * 1000003ULL) ^ ((size_t)s.vert * 10007ULL) ^ (size_t)s.hmask;
    }
};

int H, W;
long long answer = 0;

unordered_map<State, long long, Hasher> memo_next;
unordered_map<State, long long, Hasher> memo_cur;

inline bool bit(int mask, int i) { return (mask >> i) & 1; }

void dfs_row(int row, int col, int occ, int vert, int hmask, long long ways,
             unordered_map<State, long long, Hasher>& out) {
    if (col == W) {
        State ns{vert, 0, 0};
        out[ns] += ways;
        return;
    }

    if (bit(occ, col)) {
        dfs_row(row, col + 1, occ, vert, hmask, ways, out);
        return;
    }

    // Try horizontal at (row,col)-(row,col+1)
    if (col + 1 < W && !bit(occ, col + 1)) {
        bool ok = true;

        // New horizontal boundary is between col and col+1 => index col (0-based boundary index for 1..W-1)
        // Check interior point at (row, col+1), i.e. between columns col and col+1, above current row if row>0
        if (row > 0) {
            bool top = bit(memo_cur.begin()->first.vert, 0); // dummy, not used
        }

        // Need access to previous row vertical/horizontal info? We encoded:
        // current occ includes cells occupied from above, but for cross checking we need exact edge info around points.
        // For a point between rows row-1 and row and columns k-1 and k:
        // top edge exists iff previous row had horizontal boundary k in hmask_prev
        // bottom edge exists iff current row has horizontal boundary k in hmask
        // left edge exists iff previous row had vertical at column k-1
        // right edge exists iff previous row had vertical at column k
        //
        // To make this available, we process with "occ" as previous vertical occupancy only is insufficient.
        // So we need row-level DP state to include previous row's vert and hmask.
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> H >> W;

    if ((H * W) % 2) {
        cout << 0 << '\n';
        return 0;
    }

    // We use a fuller row DP storing previous row information.
    struct RowState {
        int incoming;   // cells occupied in this row by vertical dominoes from above
        int prevVert;   // previous row's top-of-vertical mask (vertical edges crossing between prev row and this row)
        int prevH;      // previous row's horizontal boundary mask
        bool operator==(const RowState& o) const {
            return incoming == o.incoming && prevVert == o.prevVert && prevH == o.prevH;
        }
    };
    struct RowHasher {
        size_t operator()(const RowState& s) const {
            return ((size_t)s.incoming * 1000003ULL) ^ ((size_t)s.prevVert * 10007ULL) ^ (size_t)s.prevH;
        }
    };

    unordered_map<RowState, long long, RowHasher> dp, ndp;
    dp[{0, 0, 0}] = 1;

    for (int r = 0; r < H; ++r) {
        ndp.clear();

        for (auto &it : dp) {
            RowState rs = it.first;
            long long ways = it.second;

            function<void(int,int,int,int)> dfs = [&](int c, int occ, int curVert, int curH) {
                if (c == W) {
                    ndp[{curVert, curVert, curH}] += ways;
                    return;
                }
                if (bit(occ, c)) {
                    dfs(c + 1, occ, curVert, curH);
                    return;
                }

                // Place horizontal domino at (r,c)-(r,c+1)
                if (c + 1 < W && !bit(occ, c + 1)) {
                    bool ok = true;
                    int boundary = c; // between c and c+1, stored in bit c for 0..W-2

                    // Check interior point above this new horizontal edge: point (r, c+1)
                    if (r > 0) {
                        bool top = bit(rs.prevH, boundary);
                        bool bottom = true;
                        bool left = bit(rs.prevVert, c);
                        bool right = bit(rs.prevVert, c + 1);
                        if (top && bottom && left && right) ok = false;
                    }

                    if (ok) {
                        dfs(c + 2, occ | (1 << c) | (1 << (c + 1)), curVert, curH | (1 << boundary));
                    }
                }

                // Place vertical domino downward at (r,c)-(r+1,c)
                if (r + 1 < H) {
                    bool ok = true;

                    // Check interior point to upper-left: (r, c), if 0<r and 0<c
                    if (r > 0 && c > 0) {
                        bool top = bit(rs.prevH, c - 1);
                        bool bottom = bit(curH, c - 1);
                        bool left = bit(rs.prevVert, c - 1);
                        bool right = true;
                        if (top && bottom && left && right) ok = false;
                    }

                    // Check interior point to upper-right: (r, c+1), if 0<r and c+1<W
                    if (ok && r > 0 && c + 1 < W) {
                        bool top = bit(rs.prevH, c);
                        bool bottom = bit(curH, c);
                        bool left = true;
                        bool right = bit(rs.prevVert, c + 1);
                        if (top && bottom && left && right) ok = false;
                    }

                    if (ok) {
                        dfs(c + 1, occ | (1 << c), curVert | (1 << c), curH);
                    }
                }
            };

            dfs(0, rs.incoming, 0, 0);
        }

        dp.swap(ndp);
    }

    long long ans = 0;
    for (auto &it : dp) {
        if (it.first.incoming == 0) ans += it.second;
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class TatamiArrangement {
    static int H, W;
    static int[][] floor;
    static int count;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        floor = new int[H][W];
        count = 0;
        solve(0, 0);
        System.out.println(count);
        sc.close();
    }

    static void solve(int r, int c) {
        if (r >= H) {
            count++;
            return;
        }
        if (c >= W) {
            solve(r + 1, 0);
            return;
        }
        if (floor[r][c] != 0) {
            solve(r, c + 1);
            return;
        }

        // Try horizontal placement (1x2)
        if (c + 1 < W && floor[r][c + 1] == 0) {
            if (canPlaceHorizontal(r, c)) {
                floor[r][c] = floor[r][c + 1] = 1;
                solve(r, c + 2);
                floor[r][c] = floor[r][c + 1] = 0;
            }
        }

        // Try vertical placement (2x1)
        if (r + 1 < H && floor[r + 1][c] == 0) {
            if (canPlaceVertical(r, c)) {
                floor[r][c] = floor[r + 1][c] = 1;
                solve(r, c + 1);
                floor[r][c] = floor[r + 1][c] = 0;
            }
        }
    }

    static boolean canPlaceHorizontal(int r, int c) {
        // Check that no cross is formed at corners
        if (r > 0 && c > 0) {
            if (floor[r - 1][c - 1] != 0 && floor[r - 1][c] != 0 
                && floor[r][c - 1] != 0) return false;
        }
        if (r > 0 && c + 1 < W - 1) {
            if (floor[r - 1][c + 1] != 0 && floor[r - 1][c + 2] != 0 
                && floor[r][c + 2] != 0) return false;
        }
        return true;
    }

    static boolean canPlaceVertical(int r, int c) {
        // Check that no cross is formed at corners
        if (r > 0 && c > 0) {
            if (floor[r - 1][c - 1] != 0 && floor[r][c - 1] != 0 
                && floor[r - 1][c] != 0) return false;
        }
        if (r + 1 < H - 1 && c > 0) {
            if (floor[r + 1][c - 1] != 0 && floor[r + 2][c - 1] != 0 
                && floor[r + 2][c] != 0) return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/*
 Tatami tilings counting.

 We count tilings of an H x W rectangle by 1x2 dominoes (tatami mats),
 with the additional tatami rule: no grid intersection may have four mat corners meeting
 (i.e. no "cross").

 Standard row-by-row DP with profile:
 For each vertical boundary between processed and unprocessed cells, we keep
 for every column:
   - whether a vertical domino from previous row occupies the current cell (occ bit)
   - the orientation of the tile covering the cell just above this boundary:
       0 = none (only possible outside board / unused)
       1 = vertical
       2 = horizontal-left-half
       3 = horizontal-right-half

 While filling current row left to right, when placing a tile we can check every newly completed
 grid intersection and forbid the case where the four surrounding cells belong to four distinct tiles.

 To test "cross", it is enough to know IDs of the four tiles around that intersection.
 We construct temporary local IDs from the already known neighboring cells and the tile being placed.

 State after finishing a row:
   nextOcc: columns where a vertical domino continues downward
   curOri : orientation types of tiles occupying this row's cells
 This becomes the next row's state.

 Input:
   height width
 Output:
   number of tatami tilings

 Works well for typical small-board tatami counting tasks.
*/
public class Main {
    static int H, W;
    static HashMap<Long, Long> memo = new HashMap<>();

    static long encodeState(int occMask, int[] ori) {
        long key = occMask;
        long mul = 1L << W;
        long t = 0;
        long p = 1;
        for (int i = 0; i < W; i++) {
            t += (long) ori[i] * p;
            p *= 4L;
        }
        return key + mul * t;
    }

    static long solveRow(int row, int occMask, int[] prevOri) {
        if (row == H) {
            return occMask == 0 ? 1L : 0L;
        }
        long stateKey = (((long) row) << 50) ^ encodeState(occMask, prevOri);
        Long cached = memo.get(stateKey);
        if (cached != null) return cached;

        int[] curOri = new int[W];
        long ans = dfsCell(row, 0, occMask, prevOri, 0, curOri);

        memo.put(stateKey, ans);
        return ans;
    }

    static long dfsCell(int row, int col, int occMask, int[] prevOri, int nextOccMask, int[] curOri) {
        if (col == W) {
            return solveRow(row + 1, nextOccMask, curOri.clone());
        }

        if (((occMask >> col) & 1) != 0) {
            // Current cell already occupied by vertical domino from above.
            curOri[col] = 1; // vertical
            long res = dfsCell(row, col + 1, occMask, prevOri, nextOccMask, curOri);
            curOri[col] = 0;
            return res;
        }

        long res = 0;

        // Try horizontal domino to the right
        if (col + 1 < W && ((occMask >> (col + 1)) & 1) == 0) {
            curOri[col] = 2;     // left half
            curOri[col + 1] = 3; // right half

            if (validAt(row, col, prevOri, curOri) && validAt(row, col + 1, prevOri, curOri)) {
                res += dfsCell(row, col + 2, occMask, prevOri, nextOccMask, curOri);
            }

            curOri[col] = 0;
            curOri[col + 1] = 0;
        }

        // Try vertical domino downward
        if (row + 1 < H) {
            curOri[col] = 1;
            if (validAt(row, col, prevOri, curOri)) {
                res += dfsCell(row, col + 1, occMask, prevOri, nextOccMask | (1 << col), curOri);
            }
            curOri[col] = 0;
        }

        return res;
    }

    // Check the intersection just above-right of cell (row,col), i.e. the grid point between
    // rows row-1,row and cols col-1,col. This intersection becomes fully known once curOri[col] is set.
    static boolean validAt(int row, int col, int[] prevOri, int[] curOri) {
        if (row == 0 || col == 0) return true;

        // Four cells:
        // A = (row-1,col-1), B = (row-1,col)
        // C = (row,col-1),   D = (row,col)
        int a = tileIdUpper(row, col, col - 1, prevOri);
        int b = tileIdUpper(row, col, col, prevOri);
        int c = tileIdLower(col - 1, curOri);
        int d = tileIdLower(col, curOri);

        if (a == 0 || b == 0 || c == 0 || d == 0) return true;

        return !(a != b && a != c && a != d && b != c && b != d && c != d);
    }

    // Unique IDs for tiles in previous row around current intersection.
    static int tileIdUpper(int row, int curCol, int upperCol, int[] prevOri) {
        int o = prevOri[upperCol];
        if (o == 1) {
            // vertical tile identified by its column
            return 1 + upperCol;
        } else if (o == 2) {
            // horizontal left half, tile anchored at upperCol
            return 1000 + upperCol;
        } else if (o == 3) {
            // horizontal right half, tile anchored at upperCol-1
            return 1000 + (upperCol - 1);
        }
        return 0;
    }

    // Unique IDs for tiles in current row around current intersection.
    static int tileIdLower(int col, int[] curOri) {
        int o = curOri[col];
        if (o == 1) {
            return 2000 + col; // current row vertical anchored at this col
        } else if (o == 2) {
            return 3000 + col;
        } else if (o == 3) {
            return 3000 + (col - 1);
        }
        return 0;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        H = fs.nextInt();
        W = fs.nextInt();

        // Symmetry: smaller width is better for profile size.
        if (W > H) {
            int t = H; H = W; W = t;
        }

        int[] initPrev = new int[W];
        long ans = solveRow(0, 0, initPrev);
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import java.util.*;

public class Main {
    static int H, W;
    static Map<Long, Long> memo = new HashMap<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            H = sc.nextInt(); W = sc.nextInt();
            if (H == 0 && W == 0) break;
            memo.clear();
            // Ensure H >= W for efficiency
            if (H < W) { int t = H; H = W; W = t; }
            long ans = solve(0, 0, 0, 0);
            System.out.println(ans);
        }
    }

    // row, col, curMask (cells filled in current row), prevSeam (vertical seams of previous row)
    static long solve(int row, int col, int curMask, int prevSeam) {
        if (row == H) return (curMask == 0) ? 1 : 0;
        long key = ((long)row << 30) | ((long)col << 20) | ((long)curMask << 10) | prevSeam;
        if (memo.containsKey(key)) return memo.get(key);
        long res = rowDP(row, col, curMask, prevSeam, 0);
        memo.put(key, res);
        return res;
    }

    static long rowDP(int row, int col, int curMask, int prevSeam, int curSeam) {
        if (col == W) {
            // curSeam is the seam for this row; check no cross with prevSeam
            // cross at boundary j means prevSeam bit j AND curSeam bit j both set
            if ((prevSeam & curSeam) != 0) return 0;
            return solve(row + 1, 0, curMask, curSeam);
        }
        long res = 0;
        boolean filled = (curMask & (1 << col)) != 0;
        if (filled) {
            int newSeam = curSeam | (col > 0 ? (1 << (col-1)) : 0);
            // seam between col-1 and col? No: seam[j] = seam between col j and j+1
            // A cell at col is filled by vertical domino from above, so seam on left (col-1,col) and right (col,col+1) boundaries
            // Actually seam depends on neighbors
            res = rowDP(row, col + 1, curMask, prevSeam, curSeam);
        } else {
            // Place vertical domino (going down)
            if (row + 1 < H) {
                res += rowDP(row, col + 1, curMask | (1 << col), prevSeam, curSeam | (col > 0 ? (1<<(col-1)) : 0));
            }
            // Place horizontal domino
            if (col + 1 < W && (curMask & (1 << (col+1))) == 0) {
                res += rowDP(row, col + 2, curMask, prevSeam, curSeam | (col > 0 ? (1<<(col-1)):0) | (1<<col) | (col+2<W?(1<<(col+1)):0));
            }
        }
        return res;
    }
}
